function createDynamicCardGridBlueprint({ id, name, presetId = 'default', templateId = '', settings = {} }) {
  return {
    id,
    templateId: String(templateId || '').trim() || 'card_grid',
    presetId,
    name,
    kind: 'card_grid',
    mode: 'dynamic',
    settings: buildCardGridPresetSettings(presetId, settings),
    editableFields: sharedDynamicGridEditableFields,
  };
}

function canonicalizeBlueprintBlockLinks(block) {
  if (!block || typeof block !== 'object') {
    return block;
  }
  const settings = block.settings && typeof block.settings === 'object'
    ? normalizeSplitLinkFieldSettings(block.settings, { stripSplitFields: true })
    : block.settings;
  return settings === block.settings
    ? block
    : { ...block, settings };
}

function canonicalizeBlueprintBlocksLinks(blocks) {
  return (Array.isArray(blocks) ? blocks : []).map(canonicalizeBlueprintBlockLinks);
}

function canonicalizeBlueprintMapLinks(blueprintsByPath) {
  return Object.fromEntries(
    Object.entries(blueprintsByPath || {}).map(([pathname, blocks]) => [
      pathname,
      canonicalizeBlueprintBlocksLinks(blocks),
    ]),
  );
}

function createDynamicColumnsBlueprint({ id, name, presetId = 'default', templateId = '', settings = {} }) {
  return {
    id,
    templateId: String(templateId || '').trim() || 'columns',
    presetId,
    name,
    kind: 'columns',
    mode: 'dynamic',
    settings: buildColumnsPresetSettings(presetId, settings),
    editableFields: columnsEditableFields,
  };
}

function createDynamicCtaBandBlueprint({ id, name, presetId = 'default', templateId = '', settings = {} }) {
  return {
    id,
    templateId: String(templateId || '').trim() || 'cta_band',
    presetId,
    name,
    kind: 'cta_band',
    mode: 'dynamic',
    settings: buildCtaBandPresetSettings(presetId, settings),
    editableFields: ctaBandEditableFields,
  };
}

