        title: '403(b) Compliance Regulations',
        titleClassName: '',
        titleHighlightsJson: '',
        subtitle: '',
        bodyHtml: '<p class="retirement-403b-group-compliance-copy">The Internal Revenue Service issued regulations on 403(b) plans that generally became effective on January 1, 2009. These regulations impact all 403(b) plans and require a written plan document that contains the material plan provisions. If AGFinancial is your exclusive service provider, compliance implementation can be easier. Compliance may be more complex if you use multiple providers.</p><p class="retirement-403b-group-compliance-copy"><strong>403(b) Guidelines of Administrative Responsibilities</strong></p><p class="retirement-403b-group-compliance-copy">AGFinancial and MBA provide multiple administrative functions for compliance with regulations; however, some administrative functions remain your responsibility as the employer fiduciary. Download the checklist that matches your organization type.</p><p class="retirement-403b-group-compliance-copy">This information is not legal or tax advice. Work with your ministry’s legal and tax advisors to ensure you have satisfied all IRS 403(b) regulation requirements.</p><p class="retirement-403b-group-compliance-copy">For assistance, contact 800.622.7526 or email 403bregs@agfinancial.org.</p>',
